package com.nbi.lookup.service;

import com.nbi.lookup.dto.*;
import com.nbi.lookup.model.Transaction;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service
public class AccountService {
    private final Map<String, AccountResponse> accounts = new HashMap<>();
    private final List<Transaction> txns = new ArrayList<>();

    public AccountService() {
        accounts.put("SAV2001", new AccountResponse("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00")));
        accounts.put("CUR3001", new AccountResponse("CUR3001", "Priya Sharma", new BigDecimal("250000.00")));
        txns.add(new Transaction("TXN-1", "SAV2001", new BigDecimal("50000")));
        txns.add(new Transaction("TXN-2", "SAV2001", new BigDecimal("12000")));
    }

    public Optional<AccountResponse> find(String id) {
        return Optional.ofNullable(accounts.get(id));
    }

    public boolean accountExists(String id) { return accounts.containsKey(id); }

    // Collection query: returns an empty list when nothing matches (NOT null).
    public List<TxnResponse> findLargeTxns(String accountId, BigDecimal min) {
        return txns.stream()
                .filter(t -> t.getAccountId().equals(accountId))
                .filter(t -> min == null || t.getAmount().compareTo(min) >= 0)
                .map(t -> new TxnResponse(t.getId(), t.getAmount()))
                .collect(Collectors.toList());
    }
}
```

```java
// ─── File: src/main/java/com/nbi/lookup/controller/AccountController.java ───
package com.nbi.lookup.controller;

import com.nbi.lookup.dto.*;
import com.nbi.lookup.service.AccountService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.util.List;

@RestController
@RequestMapping("/api/v1/accounts")
public class AccountController {

    private final AccountService service;
    public AccountController(AccountService service) { this.service = service; }

    // SINGLE resource missing → 404 Not Found.
    @GetMapping("/{id}")
    public ResponseEntity<AccountResponse> get(@PathVariable String id) {
        return service.find(id)
                .map(ResponseEntity::ok)
                .orElse(ResponseEntity.notFound().build());
    }

    // COLLECTION with no matches → 200 OK + empty array.
    // Parent missing → 404 (the account itself does not exist).
    @GetMapping("/{id}/transactions")
    public ResponseEntity<List<TxnResponse>> list(@PathVariable String id,
            @RequestParam(required = false) BigDecimal minAmount) {
        if (!service.accountExists(id)) {
            return ResponseEntity.notFound().build(); // parent missing → 404
        }
        return ResponseEntity.ok(service.findLargeTxns(id, minAmount)); // 200 even if empty
    }

    // DELETE → 204 No Content (success, no body).
    @DeleteMapping("/{id}/beneficiaries/{benId}")
    public ResponseEntity<Void> deleteBeneficiary(@PathVariable String id,
                                                  @PathVariable String benId) {
        return ResponseEntity.noContent().build(); // 204
    }
}
```
